        if reason != 'reached':
            return
    s=get_observation()['state']
    a={'left_arm_joint_state':list(s['left_arm_joint_state']),'right_arm_joint_state':origin['right_arm_joint_state'],'left_ee_joint_state':[0.0],'right_ee_joint_state':[1.0]}
    for n in range(16):
        obs,reward,terminated,truncated,info=step(a)
        if terminated or truncated:
            break
        if n>=5 and max(abs(obs['state']['right_arm_joint_state'][j]-origin['right_arm_joint_state'][j]) for j in range(6))<0.015:
            break
    print('home',n+1,obs['state'])
